DELETE FROM `itemset` WHERE `ID` IN (384101, 384102, 384103);

DELETE FROM `itemset_dbc` WHERE `ID` IN (384101, 384102, 384103);

DELETE FROM `item_set_names` WHERE `entry` IN (95200, 95201, 95202, 95203, 95204, 95205, 95206, 95207, 95208, 95209, 95210, 95211, 95212, 95213, 95214, 95215);

DELETE FROM `_仙门_仙器物品` WHERE `物品ID` BETWEEN 95100 AND 95109;

-- item_instance.durability 是 smallint unsigned，模板耐久必须限制在 65535 以内。
UPDATE `item_template`
SET `MaxDurability` = 65535
WHERE `entry` BETWEEN 95100 AND 95218
  AND `MaxDurability` > 65535;
